"""One-file, mobile-first HTML projection of the portable research bundle."""
import pathlib,json,html,markdown,datetime
P=pathlib.Path('activities/261124-001-race-StbUAJvivDc/lanes/codex');V='StbUAJvivDc';d=json.loads((P/'page-data-codex.json').read_text());esc=html.escape

def section(file,title):
 text=(P/file).read_text().split('---',2)[-1];text=text.rsplit('\n---\n',1)[0]
 return f'<section id="{file.split("-")[0]}"><h2>{esc(title)}</h2>'+markdown.markdown(text,extensions=['tables','fenced_code'])+f'<p class="file"><a href="{file}">Portable Markdown ↗</a></p></section>'
labels={n['id']:n['label'] for n in d['nodes']}
graph='<div class="table-scroll"><table><thead><tr><th>From</th><th>Relationship</th><th>To</th><th>Evidence</th></tr></thead><tbody>'
for e in d['edges']:
 graph+=f'<tr><td>{esc(labels[e["from"]])}</td><td>{esc(e["relation"])}'+(' <span class="pill">Inference</span>' if e['inference'] else '')+f'</td><td>{esc(labels[e["to"]])}</td><td><a href="{e["source_file"]}">Saved source</a></td></tr>'
graph+='</tbody></table></div>'
sources=''.join(f'<li><a href="{esc(s["url"])}">{esc(s["name"])}</a> · <a href="{s["source_file"]}">saved text</a></li>' for s in d['sources'])
body=section(f'ANSWER-v02-{V}.md','The argument')+f'<section id="expert"><h2>The expert network</h2><p>13 nodes · 13 sourced relationships. People, works and organisations from the publisher description and corresponding Range section. This is our research graph, not a diagram seen in the Short.</p>{graph}<p><a href="knowledge-graph-{V}.json">Portable graph JSON ↗</a> · <a href="knowledge-check-result.json">Provenance check ↗</a></p></section>'
for file,title in [(f'method-card-{V}.md','Use the method'),(f'feature-docs-{V}.md','The supporting capability'),(f'words-versus-sources-{V}.md','Words versus sources'),(f'quotes-sources-{V}.md','Five checked written excerpts'),(f'visual-layer-{V}.md','What we could not see'),(f'DERIVATIVES-{V}.md','Make something useful next')]:body+=section(file,title)
body+=f'''<section id="audit"><h2>Verify this in five minutes</h2><ol><li>Open the saved <a href="sources/youtube-page.txt">publisher description</a> and <a href="sources/felix-post.txt">original post</a>.</li><li>Check the five written excerpts against the <a href="exact-quotes-result.json">literal-match results</a>.</li><li>Follow graph edges to their saved sources.</li><li>Read the <a href="coverage-check-result.json">failed coverage check</a>: no timed speech or frames were recovered. Empty-input proof passes do not verify the video.</li><li>Review the <a href="CHECKLIST-codex.jsonl">C01–C20 checklist</a>, <a href="RUN-REPORT-codex.md">run report</a> and <a href="TOOLS-codex.md">reusable tools</a>.</li></ol><p><a href="DECISIONS-codex.jsonl">Decisions</a> · <a href="LOG-codex.jsonl">Clock and cost log</a> · <a href="integrity-skills-codex.json">Skill hashes</a> · <a href="proof-{V}.json">Supplied proof</a> · <a href="regression-checks-codex.json">Regression tests</a></p><h3>Primary sources saved</h3><ul>{sources}</ul></section>'''
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f4f1e9;color:#142d2b;font:17px/1.65 system-ui,sans-serif}main{max-width:1060px;margin:auto;padding:30px 24px 80px}header{background:#123e39;color:#fff;padding:52px 28px;border-radius:24px;margin-bottom:24px}header .eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:2px;color:#bbe2c8}h1{font-size:clamp(34px,6vw,62px);line-height:1.08;max-width:800px;margin:18px 0}h2{font-size:29px;line-height:1.25;margin:0 0 24px}h3{font-size:20px;margin-top:26px}a{color:#006d62;text-underline-offset:3px}header a{color:#d8f1de}nav{display:flex;gap:18px;flex-wrap:wrap;margin-top:25px}.notice{padding:19px 22px;background:#fff0cf;border-left:5px solid #b36a13;border-radius:8px;margin:24px 0}section{background:white;border:1px solid #dcded5;border-radius:18px;padding:30px;margin:25px 0;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #e1e6df}th{background:#e9f0e8}.table-scroll{overflow-x:auto}code,pre{font-size:14px}pre{background:#142d2b;color:#e5f3e6;padding:20px;white-space:pre-wrap;border-radius:12px;overflow:auto}.pill{font-size:11px;background:#fff0cf;padding:3px 6px;border-radius:8px}blockquote{border-left:3px solid #65a392;padding:5px 18px;margin:20px 0;background:#f0f7f1}.file,footer{font-size:13px;color:#506b64}.button{display:inline-block;border:1px solid #cae9d0;border-radius:25px;padding:8px 14px;text-decoration:none}.metrics{display:flex;flex-wrap:wrap;gap:10px}.metrics span{background:#e8f1e6;padding:8px 14px;border-radius:10px}@media(max-width:600px){main{padding:12px}header{padding:30px 22px}section{padding:22px 16px}td,th{padding:8px;font-size:12px}}@media print{body{background:white}header{background:white;color:#123e39}nav,.file{display:none}section{break-inside:avoid;border:0;padding:15px}a{color:inherit}}'''
page=f'''<!doctype html><html lang="en-NZ"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A source-grounded method for better presentations: actions, disciplines and evidence. Includes an auditable expert graph and honest video-access limits."><meta name="author" content="ChatGPT Codex; Hamish McGregor"><title>Actions before slides · codex race bundle</title><style>{css}</style></head><body><main><header><div class="eyebrow">CHaiMPION · codex lane · 24 November 2026</div><h1>Better presentations begin with better actions.</h1><p>Define the decision. Borrow the disciplines. Use their methods.</p><nav><a href="#expert">Expert network</a><a href="#method">Method card</a><a href="#feature">Feature</a><a href="#audit">Audit</a><a href="https://www.youtube.com/shorts/{V}">Original Short ↗</a></nav></header><div class="notice"><strong>Research checked. Video evidence blocked.</strong> This page uses the publisher's description and primary written sources. Narrator quotations, exact timings and visual claims remain unverified.</div><div class="metrics"><span>13 expert nodes</span><span>7 graph source URLs saved</span><span>5 written excerpts checked</span><span>7 derivative ideas</span></div>{body}<footer>Prepared by ChatGPT Codex with Hamish McGregor · source surface: chatgpt · model: GPT-6 · reply: 4 · project: 261124-001 · conversation URL unavailable.<br>All diagrams and tables are backed by portable Markdown and JSON in this lane. No client data used.</footer></main></body></html>'''
(P/'index.html').write_text(page);print('Built',len(page),'characters; no external scripts, styles or image dependencies')
